     4→// ==================== 자동 완성 ====================
     5→
     6→class CompletionItem {
     7→  final String label;
     8→  final String detail;
     9→  final String documentation;
    10→  final String insertText;
    11→  final CompletionItemKind kind;
    12→
    13→  CompletionItem({
    14→    required this.label,
    15→    required this.detail,
    16→    required this.documentation,
    17→    required this.insertText,
    18→    required this.kind,
    19→  });
    20→}
    21→
    22→enum CompletionItemKind {
    23→  keyword,
    24→  function,
    25→  variable,
    26→  type,
    27→  module,
    28→  snippet,
    29→}
    30→
    31→class AutocompleteProvider {
    32→  static const List<String> keywords = [
    33→    'let',
    34→    'if',
    35→    'else',
    36→    'for',
    37→    'while',
    38→    'fn',
    39→    'return',
    40→    'break',
    41→    'continue',
    42→    'match',
    43→    'true',
    44→    'false',
    45→    'nil',
    46→  ];
    47→
    48→  static const List<String> builtinFunctions = [
    49→    'print',
    50→    'println',
    51→    'len',
    52→    'push',
    53→    'pop',
    54→    'append',
    55→    'slice',
    56→    'contains',
    57→    'indexOf',
    58→    'toLowerCase',
    59→    'toUpperCase',
    60→    'trim',
    61→    'split',
    62→    'join',
    63→  ];
    64→
    65→  static const List<String> builtinTypes = [
    66→    'i32',
    67→    'i64',
    68→    'f32',
    69→    'f64',
    70→    'string',
    71→    'bool',
    72→    'array',
    73→    'object',
    74→  ];
    75→
    76→  /// 현재 커서 위치에서 자동 완성 제안 조회
    77→  static List<CompletionItem> getCompletions(
    78→    String code,
    79→    int position,
    80→  ) {
    81→    final completions = <CompletionItem>[];
    82→
    83→    // 커서 앞 텍스트 추출
    84→    final beforeCursor = code.substring(0, position);
    85→    final lastWord = _extractLastWord(beforeCursor);
    86→
    87→    // 키워드 제안
    88→    for (final keyword in keywords) {
    89→      if (keyword.startsWith(lastWord)) {
    90→        completions.add(CompletionItem(
    91→          label: keyword,
    92→          detail: 'Keyword',
    93→          documentation: 'FreeLang keyword: $keyword',
    94→          insertText: keyword,
    95→          kind: CompletionItemKind.keyword,
    96→        ));
    97→      }
    98→    }
    99→
   100→    // 함수 제안
   101→    for (final func in builtinFunctions) {
   102→      if (func.startsWith(lastWord)) {
   103→        completions.add(CompletionItem(
   104→          label: func,
   105→          detail: 'Function',
   106→          documentation: 'Built-in function: $func()',
   107→          insertText: '$func(\${1})',
   108→          kind: CompletionItemKind.function,
   109→        ));
   110→      }
   111→    }
   112→
   113→    // 타입 제안
   114→    for (final type in builtinTypes) {
   115→      if (type.startsWith(lastWord)) {
   116→        completions.add(CompletionItem(
   117→          label: type,
   118→          detail: 'Type',
   119→          documentation: 'FreeLang type: $type',
   120→          insertText: type,
   121→          kind: CompletionItemKind.type,
   122→        ));
   123→      }
   124→    }
   125→
   126→    // 스니펫 제안
   127→    final snippets = _getSnippets();
   128→    for (final snippet in snippets) {
   129→      if (snippet.label.startsWith(lastWord)) {
   130→        completions.add(snippet);
   131→      }
   132→    }
   133→
   134→    return completions;
   135→  }
   136→
   137→  static String _extractLastWord(String text) {
   138→    final match = RegExp(r'\w*$').firstMatch(text);
   139→    return match?.group(0) ?? '';
   140→  }
   141→
   142→  static List<CompletionItem> _getSnippets() {
   143→    return [
   144→      CompletionItem(
   145→        label: 'fn',
   146→        detail: 'Snippet',
   147→        documentation: 'Function declaration',
   148→        insertText: 'fn \${1:name}(\${2:params}) { \${3} }',
   149→        kind: CompletionItemKind.snippet,
   150→      ),
   151→      CompletionItem(
   152→        label: 'if',
   153→        detail: 'Snippet',
   154→        documentation: 'If statement',
   155→        insertText: 'if (\${1:condition}) { \${2} }',
   156→        kind: CompletionItemKind.snippet,
   157→      ),
   158→      CompletionItem(
   159→        label: 'for',
   160→        detail: 'Snippet',
   161→        documentation: 'For loop',
   162→        insertText: 'for (let i = 0; i < \${1:length}; i++) { \${2} }',
   163→        kind: CompletionItemKind.snippet,
   164→      ),
   165→      CompletionItem(
   166→        label: 'while',
   167→        detail: 'Snippet',
   168→        documentation: 'While loop',
   169→        insertText: 'while (\${1:condition}) { \${2} }',
   170→        kind: CompletionItemKind.snippet,
   171→      ),
   172→    ];
   173→  }
   174→}
