    84→// ==================== LSP 클라이언트 ====================
    85→
    86→class FreeLangLSPClient {
    87→  static final FreeLangLSPClient _instance = FreeLangLSPClient._internal();
    88→
    89→  factory FreeLangLSPClient() {
    90→    return _instance;
    91→  }
    92→
    93→  FreeLangLSPClient._internal();
    94→
    95→  // 내장 FreeLang 키워드 & 내장 함수 (로컬 검증)
    96→  final _keywords = <String>{
    97→    'let', 'fn', 'if', 'else', 'match', 'while', 'for', 'return',
    98→    'break', 'continue', 'true', 'false', 'nil', 'import', 'module',
    99→    'record', 'variant', 'type', 'impl', 'pub', 'mut', 'ref',
   100→  };
   101→
   102→  final _builtins = <String>{
   103→    'print', 'println', 'input', 'len', 'push', 'pop', 'reverse',
   104→    'map', 'filter', 'fold', 'range', 'zip', 'unzip', 'assert',
   105→    'abs', 'min', 'max', 'sort', 'join', 'split', 'chars',
   106→    'to_string', 'to_int', 'to_float',
   107→  };
   108→
   109→  /// 코드 검증 (진단)
   110→  /// 간단한 구문 검사: 괄호, 따옴표 매칭 등
   111→  Future<List<DiagnosticItem>> validateCode(String code) async {
   112→    return Future.delayed(const Duration(milliseconds: 100), () {
   113→      final diagnostics = <DiagnosticItem>[];
   114→      final lines = code.split('\n');
   115→
   116→      for (int lineIdx = 0; lineIdx < lines.length; lineIdx++) {
   117→        final line = lines[lineIdx];
   118→
   119→        // 1. 괄호 짝 확인
   120→        int parenCount = 0;
   121→        int bracketCount = 0;
   122→        int braceCount = 0;
   123→        bool inString = false;
   124→
   125→        for (int i = 0; i < line.length; i++) {
   126→          final ch = line[i];
   127→
   128→          // 문자열 내부는 무시
   129→          if (ch == '"' && (i == 0 || line[i - 1] != '\\')) {
   130→            inString = !inString;
   131→          }
   132→
   133→          if (!inString) {
   134→            switch (ch) {
   135→              case '(':
   136→                parenCount++;
   137→                break;
   138→              case ')':
   139→                parenCount--;
   140→                break;
   141→              case '[':
   142→                bracketCount++;
   143→                break;
   144→              case ']':
   145→                bracketCount--;
   146→                break;
   147→              case '{':
   148→                braceCount++;
   149→                break;
   150→              case '}':
   151→                braceCount--;
   152→                break;
   153→            }
   154→          }
   155→        }
   156→
   157→        // 괄호 불일치
   158→        if (parenCount < 0) {
   159→          diagnostics.add(DiagnosticItem(
   160→            line: lineIdx,
   161→            startCol: line.lastIndexOf(')'),
   162→            endCol: line.lastIndexOf(')') + 1,
   163→            message: '예상치 않은 닫는 괄호 )',
   164→            severity: 1, // error
   165→          ));
   166→        }
   167→        if (bracketCount < 0) {
   168→          diagnostics.add(DiagnosticItem(
   169→            line: lineIdx,
   170→            startCol: line.lastIndexOf(']'),
   171→            endCol: line.lastIndexOf(']') + 1,
   172→            message: '예상치 않은 닫는 괄호 ]',
   173→            severity: 1,
   174→          ));
   175→        }
   176→        if (braceCount < 0) {
   177→          diagnostics.add(DiagnosticItem(
   178→            line: lineIdx,
   179→            startCol: line.lastIndexOf('}'),
   180→            endCol: line.lastIndexOf('}') + 1,
   181→            message: '예상치 않은 닫는 괄호 }',
   182→            severity: 1,
   183→          ));
   184→        }
   185→
   186→        // 따옴표 불일치
   187→        if (inString) {
   188→          diagnostics.add(DiagnosticItem(
   189→            line: lineIdx,
   190→            startCol: 0,
   191→            endCol: line.length,
   192→            message: '닫혀있지 않은 따옴표',
   193→            severity: 1,
   194→          ));
   195→        }
   196→
   197→        // 2. 미사용 변수 경고 (간단한 휴리스틱)
   198→        final letMatch = RegExp(r'let\s+(\w+)').allMatches(line);
   199→        for (final match in letMatch) {
   200→          final varName = match.group(1);
   201→          if (varName != null && !_isVariableUsed(code, varName, lineIdx)) {
   202→            diagnostics.add(DiagnosticItem(
   203→              line: lineIdx,
   204→              startCol: match.start,
   205→              endCol: match.end,
   206→              message: '미사용 변수: $varName',
   207→              severity: 2, // warning
   208→            ));
   209→          }
   210→        }
   211→      }
   212→
   213→      return diagnostics;
   214→    });
   215→  }
   216→
   217→  /// 자동완성 제안
   218→  Future<List<CompletionItem>> getCompletions(
   219→    String code,
   220→    int line,
   221→    int col,
   222→  ) async {
   223→    return Future.delayed(const Duration(milliseconds: 50), () {
   224→      final completions = <CompletionItem>[];
   225→      final lines = code.split('\n');
   226→
   227→      if (line >= lines.length) return completions;
   228→
   229→      final currentLine = lines[line];
   230→      final prefix = _getWordPrefix(currentLine, col);
   231→
   232→      // 키워드 제안
   233→      for (final keyword in _keywords) {
   234→        if (keyword.startsWith(prefix)) {
   235→          completions.add(CompletionItem(
   236→            label: keyword,
   237→            kind: 1, // keyword
   238→            detail: 'FreeLang 키워드',
   239→            insertText: keyword,
   240→          ));
   241→        }
   242→      }
   243→
   244→      // 내장함수 제안
   245→      for (final builtin in _builtins) {
   246→        if (builtin.startsWith(prefix)) {
   247→          completions.add(CompletionItem(
   248→            label: builtin,
   249→            kind: 2, // function
   250→            detail: '내장 함수',
   251→            insertText: '$builtin()',
   252→          ));
   253→        }
   254→      }
   255→
   256→      // 이전 줄에서 정의된 변수 제안
   257→      final variables = _extractVariables(lines, line);
   258→      for (final varName in variables) {
   259→        if (varName.startsWith(prefix) && varName != prefix) {
   260→          completions.add(CompletionItem(
   261→            label: varName,
   262→            kind: 3, // variable
   263→            detail: '변수',
   264→            insertText: varName,
   265→          ));
   266→        }
   267→      }
   268→
   269→      // 정렬 및 중복 제거
   270→      completions.sort((a, b) => a.label.compareTo(b.label));
   271→      return completions
   272→          .fold<List<CompletionItem>>([], (acc, item) {
   273→        if (acc.isEmpty || acc.last.label != item.label) {
   274→          acc.add(item);
   275→        }
   276→        return acc;
   277→      }).take(10).toList();
   278→    });
   279→  }
   280→
   281→  /// 호버 정보 (함수/변수 설명)
   282→  Future<HoverInfo?> getHoverInfo(
   283→    String code,
   284→    int line,
   285→    int col,
   286→  ) async {
   287→    return Future.delayed(const Duration(milliseconds: 50), () {
   288→      final lines = code.split('\n');
   289→      if (line >= lines.length) return null;
   290→
   291→      final currentLine = lines[line];
   292→      final word = _getWordAtPosition(currentLine, col);
   293→
   294→      if (word == null) return null;
   295→
   296→      // 키워드 설명
   297→      if (_keywords.contains(word)) {
   298→        return HoverInfo(content: '**$word** - FreeLang 키워드');
   299→      }
   300→
   301→      // 내장함수 설명
   302→      if (_builtins.contains(word)) {
   303→        final descriptions = {
   304→          'print': 'print(value) - 값을 출력합니다',
   305→          'len': 'len(arr) - 배열의 길이를 반환합니다',
   306→          'map': 'map(arr, fn) - 배열의 각 요소에 함수를 적용합니다',
   307→          'filter': 'filter(arr, fn) - 조건을 만족하는 요소를 필터링합니다',
   308→          'fold': 'fold(arr, init, fn) - 배열을 축약합니다',
   309→          'range': 'range(start, end) - start부터 end까지의 범위를 생성합니다',
   310→        };
   311→        return HoverInfo(content: descriptions[word] ?? '**$word** - 내장 함수');
   312→      }
   313→
   314→      return null;
   315→    });
   316→  }
   317→
   318→  // ==================== 헬퍼 메서드 ====================
   319→
   320→  String _getWordPrefix(String line, int col) {
   321→    int start = col - 1;
   322→    while (start >= 0 && /[a-zA-Z0-9_]/.hasMatch(line[start])) {
   323→      start--;
   324→    }
   325→    return line.substring(start + 1, col);
   326→  }
   327→
   328→  String? _getWordAtPosition(String line, int col) {
   329→    int start = col;
   330→    int end = col;
   331→
   332→    while (start > 0 && /[a-zA-Z0-9_]/.hasMatch(line[start - 1])) {
   333→      start--;
   334→    }
   335→    while (end < line.length && /[a-zA-Z0-9_]/.hasMatch(line[end])) {
   336→      end++;
   337→    }
   338→
   339→    if (start == end) return null;
   340→    return line.substring(start, end);
   341→  }
   342→
   343→  Set<String> _extractVariables(List<String> lines, int upToLine) {
   344→    final variables = <String>{};
   345→    final regex = RegExp(r'let\s+(\w+)');
   346→
   347→    for (int i = 0; i < upToLine && i < lines.length; i++) {
   348→      final matches = regex.allMatches(lines[i]);
   349→      for (final match in matches) {
   350→        final varName = match.group(1);
   351→        if (varName != null) {
   352→          variables.add(varName);
   353→        }
   354→      }
   355→    }
   356→
   357→    return variables;
   358→  }
   359→
   360→  bool _isVariableUsed(String code, String varName, int definitionLine) {
   361→    final lines = code.split('\n');
   362→    final usageRegex = RegExp(r'\b$varName\b');
   363→
   364→    int usageCount = 0;
   365→    for (int i = definitionLine; i < lines.length; i++) {
   366→      usageCount += usageRegex.allMatches(lines[i]).length;
   367→    }
   368→
   369→    // 정의 자체를 제외 (최소 2번 이상 나타나야 함: 정의 + 사용)
   370→    return usageCount > 1;
   371→  }
   372→}
