# 예상 결과: 14개 테스트 모두 PASS

# 3. 전체 테스트 실행
flutter test
```

// type_system.dart - 타입 시스템 데이터 모델
// FreeLang의 기본 타입, 제네릭, 함수 타입 정의

/// 모든 FreeLang 타입의 기반 추상 클래스
abstract class FreeLangType {
  String get name;

  /// 이 타입을 다른 타입에 할당할 수 있는지 검사
  bool isAssignableTo(FreeLangType other);

  @override
  String toString() => name;
}

/// 원시 타입 (i32, string, bool 등)
class PrimitiveType extends FreeLangType {
  @override
  final String name;

  PrimitiveType(this.name);

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is PrimitiveType) {
      return name == other.name;
    }
    if (other is PrimitiveType && other.name == 'unknown') {
      return true; // unknown 타입에는 모든 타입 할당 가능
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is PrimitiveType &&
          runtimeType == other.runtimeType &&
          name == other.name;

  @override
  int get hashCode => name.hashCode;
}

/// 배열 타입 (Array<T>)
class ArrayType extends FreeLangType {
  final FreeLangType elementType;

  ArrayType(this.elementType);

  @override
  String get name => 'array<${elementType.name}>';

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is ArrayType) {
      return elementType.isAssignableTo(other.elementType);
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ArrayType &&
          runtimeType == other.runtimeType &&
          elementType == other.elementType;

  @override
  int get hashCode => elementType.hashCode;
}

/// 맵 타입 (Map<K, V>)
class MapType extends FreeLangType {
  final FreeLangType keyType;
