// type_inference.dart - 타입 추론 엔진
// 리터럴, 표현식, 이진 연산의 타입을 자동으로 추론

import 'type_system.dart';

/// IDE 인라인 타입 힌트 표시용 데이터 클래스
class TypeHint {
  final int line;
  final int column;
  final String variableName;
  final FreeLangType inferredType;

  TypeHint({
    required this.line,
    required this.column,
    required this.variableName,
    required this.inferredType,
  });

  @override
  String toString() =>
      '$variableName: ${inferredType.name} (line $line:$column)';
}

/// 타입 추론 엔진 (정적 메서드 기반)
class TypeInferrer {
  /// 코드에서 추론 가능한 모든 타입 힌트 추출
  static List<TypeHint> inferAll(String code) {
    final hints = <TypeHint>[];
    final lines = code.split('\n');

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];
      final variableMatch =
          RegExp(r'let\s+(\w+)\s*(?::|\s*=)').firstMatch(line);

      if (variableMatch != null) {
        final varName = variableMatch.group(1)!;
        final column = variableMatch.start(1);

        // 타입 주석이 있으면 스킵
        if (line.contains('let $varName:')) {
          continue;
        }

        // 할당값에서 타입 추론
        final value = _extractAssignmentValue(line);
        if (value != null) {
          final inferredType = inferLiteral(value);
          if (inferredType != FreeLangTypes.unknown) {
            hints.add(TypeHint(
              line: i,
              column: column,
              variableName: varName,
              inferredType: inferredType,
            ));
          }
        }
      }
    }

    return hints;
  }

  /// 단일 표현식의 타입 추론
  static FreeLangType inferExpression(String expr, TypeEnvironment env) {
    final trimmed = expr.trim();

    // 리터럴 타입 추론
    final literalType = inferLiteral(trimmed);
    if (literalType != FreeLangTypes.unknown) {
      return literalType;
    }

    // 변수 타입 추론
    final varType = env.lookup(trimmed);
    if (varType != null) {
      return varType;
    }

    // 이진 연산 추론 (간단한 패턴)
    for (final op in ['+', '-', '*', '/', '>', '<', '==', '!=', '&&', '||']) {
      if (trimmed.contains(op)) {
        final parts = trimmed.split(op);
        if (parts.length == 2) {
          final leftType = inferExpression(parts[0].trim(), env);
          final rightType = inferExpression(parts[1].trim(), env);
          return inferBinaryOp(leftType, op, rightType);
        }
      }
    }

    return FreeLangTypes.unknown;
  }

  /// 리터럴 값의 타입 추론
  /// "10" -> i32, "3.14" -> f64, '"hello"' -> string, "true"/"false" -> bool
  static FreeLangType inferLiteral(String value) {
    final trimmed = value.trim();

    // 문자열 리터럴
    if ((trimmed.startsWith('"') && trimmed.endsWith('"')) ||
        (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
      return FreeLangTypes.string;
    }

    // bool 리터럴
    if (trimmed == 'true' || trimmed == 'false') {
      return FreeLangTypes.bool_;
    }

    // nil 리터럴
    if (trimmed == 'nil') {
      return FreeLangTypes.nil;
    }

    // 실수 리터럴 (점 포함)
    if (RegExp(r'^-?\d+\.\d+$').hasMatch(trimmed)) {
      // 명시적으로 지수 표기법이 없으면 f64
      if (trimmed.endsWith('f')) {
        return FreeLangTypes.f32;
      }
      return FreeLangTypes.f64;
    }

    // 정수 리터럴
    if (RegExp(r'^-?\d+$').hasMatch(trimmed)) {
      // 명시적 타입 지정이 없으면 i32 (기본값)
      if (trimmed.endsWith('L')) {
        return FreeLangTypes.i64;
      }
      return FreeLangTypes.i32;
    }

    return FreeLangTypes.unknown;
  }

  /// 이진 연산 결과 타입 추론
  /// i32 + i32 -> i32, string + string -> string, i32 > i32 -> bool, 등
  static FreeLangType inferBinaryOp(
    FreeLangType left,
    String op,
    FreeLangType right,
  ) {
    // 비교 연산자는 항상 bool
    if (['>', '<', '>=', '<=', '==', '!=', '&&', '||'].contains(op)) {
      // 하지만 양쪽 타입이 호환 가능해야 함
      if (left.isAssignableTo(right) || right.isAssignableTo(left)) {
        return FreeLangTypes.bool_;
      }
      return FreeLangTypes.unknown;
    }

    // 산술 연산: 양쪽 타입이 같아야 함
    if (['+', '-', '*', '/'].contains(op)) {
      if (left is PrimitiveType && right is PrimitiveType) {
        if (left.name == right.name) {
          return left; // i32 + i32 = i32, f64 + f64 = f64, string + string = string
        }
      }
    }

    return FreeLangTypes.unknown;
  }

  /// 할당문에서 값 추출 (간단한 파싱)
  static String? _extractAssignmentValue(String line) {
    // 'let x = value' 패턴
    final match = RegExp(r'let\s+\w+\s*=\s*(.+)$').firstMatch(line);
    if (match != null) {
      return match.group(1)?.trim();
    }
    return null;
  }
}

