import 'type_system.dart';
import 'type_inference.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 정적 타입 검사기 (Linter.lint()과 동일한 반환 타입)
class TypeChecker {
  /// 코드의 모든 타입 오류를 진단 목록으로 반환
  static List<Diagnostic> check(String code) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');
    final globalEnv = TypeEnvironment();

    // 변수 선언 타입 검사
    diagnostics.addAll(_checkVariableDeclarations(lines, globalEnv));

    // if/while 조건식 타입 검사
    diagnostics.addAll(_checkConditionTypes(lines, globalEnv));

    // 함수 반환 타입 검사 (기본)
    diagnostics.addAll(_checkReturnTypes(lines, globalEnv));

    return diagnostics;
  }

  /// 변수 선언 및 할당 타입 검사
  /// let x: i32 = "hello" -> type-mismatch 오류
  /// let x: unknown_type = 10 -> unknown-type 경고
  static List<Diagnostic> _checkVariableDeclarations(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // let x: i32 = value 패턴
      final annotatedMatch = RegExp(r'let\s+(\w+)\s*:\s*(\w+)\s*=\s*(.+)')
          .firstMatch(line);
      if (annotatedMatch != null) {
        final varName = annotatedMatch.group(1)!;
        final typeStr = annotatedMatch.group(2)!;
        final value = annotatedMatch.group(3)!;

        // 선언된 타입 파싱
        final declaredType = FreeLangTypes.fromString(typeStr);
        if (declaredType == null) {
          // 알 수 없는 타입
          diagnostics.add(Diagnostic(
            line: i,
            column: annotatedMatch.start(2),
            message: "Unknown type '$typeStr'",
            severity: DiagnosticSeverity.warning,
            code: 'unknown-type',
          ));
          continue;
        }

        // 할당값 타입 추론
        final inferredType = TypeInferrer.inferLiteral(value);

        // 타입 호환성 검사
        if (inferredType != FreeLangTypes.unknown &&
            !inferredType.isAssignableTo(declaredType)) {
          diagnostics.add(Diagnostic(
            line: i,
            column: annotatedMatch.start(3),
            message:
                "Type mismatch: cannot assign ${inferredType.name} to ${declaredType.name}",
            severity: DiagnosticSeverity.error,
            code: 'type-mismatch',
          ));
        }

        // 환경에 바인딩
        env.define(varName, declaredType);
      }

      // let x = value 패턴 (타입 추론)
      final inferMatch =
          RegExp(r'let\s+(\w+)\s*=\s*(.+)$').firstMatch(line);
      if (inferMatch != null && !line.contains(':')) {
        final varName = inferMatch.group(1)!;
        final value = inferMatch.group(2)!;

        final inferredType = TypeInferrer.inferLiteral(value);
        env.define(varName, inferredType);
      }
    }

    return diagnostics;
  }

  /// if/while 조건식이 bool 타입인지 검사
  /// if "string" -> invalid-condition-type 오류
  static List<Diagnostic> _checkConditionTypes(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // if (condition) 패턴
      final ifMatch = RegExp(r'if\s+\((.+?)\)').firstMatch(line);
      if (ifMatch != null) {
        final condition = ifMatch.group(1)!.trim();
        final condType = TypeInferrer.inferExpression(condition, env);

        if (condType != FreeLangTypes.unknown &&
            condType != FreeLangTypes.bool_) {
          diagnostics.add(Diagnostic(
            line: i,
            column: ifMatch.start(1),
            message:
                "Type error: if condition must be bool, got ${condType.name}",
            severity: DiagnosticSeverity.error,
            code: 'invalid-condition-type',
          ));
        }
      }

      // while (condition) 패턴
      final whileMatch = RegExp(r'while\s+\((.+?)\)').firstMatch(line);
      if (whileMatch != null) {
        final condition = whileMatch.group(1)!.trim();
        final condType = TypeInferrer.inferExpression(condition, env);

        if (condType != FreeLangTypes.unknown &&
            condType != FreeLangTypes.bool_) {
          diagnostics.add(Diagnostic(
            line: i,
            column: whileMatch.start(1),
            message:
                "Type error: while condition must be bool, got ${condType.name}",
            severity: DiagnosticSeverity.error,
            code: 'invalid-condition-type',
          ));
        }
      }
    }

    return diagnostics;
  }

  /// 함수 반환 타입 검사
  /// fn foo() -> i32 { "hello" } -> return-type-mismatch 오류
  static List<Diagnostic> _checkReturnTypes(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    // 함수 정의 찾기: fn name() -> type { ... }
    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];
      final fnMatch = RegExp(r'fn\s+\w+\s*\(\s*\)\s*->\s*(\w+)\s*\{')
          .firstMatch(line);

      if (fnMatch != null) {
        final returnTypeStr = fnMatch.group(1)!;
        final expectedType = FreeLangTypes.fromString(returnTypeStr);

        if (expectedType == null) {
          diagnostics.add(Diagnostic(
            line: i,
            column: fnMatch.start(1),
            message: "Unknown return type '$returnTypeStr'",
            severity: DiagnosticSeverity.warning,
            code: 'unknown-type',
          ));
          continue;
        }

        // 함수 본문에서 마지막 반환값 찾기
        var braceCount = 1;
        var endLine = i;
        for (int j = i + 1; j < lines.length && braceCount > 0; j++) {
          braceCount += '{'.allMatches(lines[j]).length;
          braceCount -= '}'.allMatches(lines[j]).length;
          endLine = j;
        }

        // 함수 본문의 마지막 값
        if (endLine < lines.length) {
          final lastLine = lines[endLine].trim();
          if (!lastLine.isEmpty && !lastLine.startsWith('//')) {
            final actualType = TypeInferrer.inferExpression(lastLine, env);
            if (actualType != FreeLangTypes.unknown &&
                !actualType.isAssignableTo(expectedType)) {
              diagnostics.add(Diagnostic(
                line: endLine,
                column: 0,
                message:
                    "Return type mismatch: expected ${expectedType.name}, got ${actualType.name}",
                severity: DiagnosticSeverity.error,
                code: 'return-type-mismatch',
              ));
            }
          }
        }
      }
    }

    return diagnostics;
  }
}

