    });

    test('Test 3: fromString() 타입 파싱', () {
      expect(FreeLangTypes.fromString('i32'), FreeLangTypes.i32);
      expect(FreeLangTypes.fromString('string'), FreeLangTypes.string);
      expect(FreeLangTypes.fromString('bool'), FreeLangTypes.bool_);
      expect(FreeLangTypes.fromString('unknown_type'), isNull);
    });

    test('Test 4: ArrayType 요소 타입 검사', () {
      final arrayI32 = ArrayType(FreeLangTypes.i32);
      final arrayI32_2 = ArrayType(FreeLangTypes.i32);
      final arrayString = ArrayType(FreeLangTypes.string);

      expect(arrayI32.isAssignableTo(arrayI32_2), true);
      expect(arrayI32.isAssignableTo(arrayString), false);
      expect(arrayI32.name, 'array<i32>');
    });

    test('Test 5: FunctionType 파라미터 타입 검사', () {
      final fn1 = FunctionType(
        paramTypes: [FreeLangTypes.i32, FreeLangTypes.string],
        returnType: FreeLangTypes.bool_,
      );
      final fn2 = FunctionType(
        paramTypes: [FreeLangTypes.i32, FreeLangTypes.string],
        returnType: FreeLangTypes.bool_,
      );
      final fn3 = FunctionType(
        paramTypes: [FreeLangTypes.string, FreeLangTypes.i32],
        returnType: FreeLangTypes.bool_,
      );

      expect(fn1.isAssignableTo(fn2), true);
      expect(fn1.isAssignableTo(fn3), false);
      expect(
        fn1.name,
        'fn(i32, string) -> bool',
      );
    });
  });

  group('TypeInferrer - 타입 추론', () {
    test('Test 6: 정수 리터럴 -> i32', () {
      expect(TypeInferrer.inferLiteral('10'), FreeLangTypes.i32);
      expect(TypeInferrer.inferLiteral('-42'), FreeLangTypes.i32);
      expect(TypeInferrer.inferLiteral('0'), FreeLangTypes.i32);
    });

    test('Test 7: 실수 리터럴 -> f64', () {
      expect(TypeInferrer.inferLiteral('3.14'), FreeLangTypes.f64);
      expect(TypeInferrer.inferLiteral('-2.5'), FreeLangTypes.f64);
      expect(TypeInferrer.inferLiteral('0.0'), FreeLangTypes.f64);
    });

    test('Test 8: 문자열 리터럴 -> string', () {
      expect(TypeInferrer.inferLiteral('"hello"'), FreeLangTypes.string);
      expect(TypeInferrer.inferLiteral("'world'"), FreeLangTypes.string);
      expect(TypeInferrer.inferLiteral('""'), FreeLangTypes.string);
    });

    test('Test 9: bool 리터럴 -> bool', () {
      expect(TypeInferrer.inferLiteral('true'), FreeLangTypes.bool_);
      expect(TypeInferrer.inferLiteral('false'), FreeLangTypes.bool_);
    });

    test('Test 10: i32 + i32 -> i32', () {
      final result = TypeInferrer.inferBinaryOp(
        FreeLangTypes.i32,
        '+',
        FreeLangTypes.i32,
      );
      expect(result, FreeLangTypes.i32);
    });

    test('Test 11: i32 > i32 -> bool', () {
      final result = TypeInferrer.inferBinaryOp(
        FreeLangTypes.i32,
        '>',
        FreeLangTypes.i32,
      );
      expect(result, FreeLangTypes.bool_);
    });

    test('Test 12: string + string -> string', () {
      final result = TypeInferrer.inferBinaryOp(
        FreeLangTypes.string,
        '+',
        FreeLangTypes.string,
      );
      expect(result, FreeLangTypes.string);
    });
  });

  group('TypeChecker - 정적 타입 검사', () {
    test('Test 13: 올바른 타입 선언 -> 오류 없음', () {
      const code = '''let x: i32 = 10
let y: string = "hello"
let z: bool = true''';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
        true,
      );
    });

    test('Test 14: 타입 불일치 -> type-mismatch 오류', () {
      const code = 'let x: i32 = "hello"';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.any((d) => d.code == 'type-mismatch'),
        true,
      );
    });

    test('Test 15: string -> i32 할당 불가', () {
      const code = '''let msg: string = "world"
let num: i32 = msg''';

      final diagnostics = TypeChecker.check(code);
      final errors = diagnostics.where((d) => d.code == 'type-mismatch');
      expect(errors.isNotEmpty, true);
    });

    test('Test 16: bool 조건식 -> OK', () {
      const code = '''let flag: bool = true
if flag { print "yes" }''';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics
            .where((d) => d.code == 'invalid-condition-type')
            .isEmpty,
        true,
      );
    });

    test('Test 17: string 조건식 -> invalid-condition-type 오류', () {
      const code = 'if "string" { print "wrong" }';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.any((d) => d.code == 'invalid-condition-type'),
        true,
      );
    });

    test('Test 18: 타입 추론 (annotation 없음) -> 오류 없음', () {
      const code = '''let x = 42
let y = "hello"
if false { print y }''';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
        true,
      );
    });

    test('Test 19: 알 수 없는 타입 -> unknown-type 경고', () {
      const code = 'let x: unknown_type = 10';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.any((d) => d.code == 'unknown-type'),
        true,
      );
    });

    test('Test 20: 완전한 코드 -> 오류 없음', () {
      const code = '''let num: i32 = 100
let text: string = "FreeLang"
let ok: bool = true
if ok {
  print num
  print text
}''';

      final diagnostics = TypeChecker.check(code);
      expect(
        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
        true,
      );
    });
  });

  group('TypeEnvironment - 타입 환경 관리', () {
    test('변수 정의 및 조회', () {
      final env = TypeEnvironment();
      env.define('x', FreeLangTypes.i32);

      expect(env.lookup('x'), FreeLangTypes.i32);
      expect(env.lookup('y'), isNull);
    });

    test('자식 스코프 독립성', () {
      final parent = TypeEnvironment();
      parent.define('x', FreeLangTypes.i32);

      final child = parent.createChild();
      child.define('y', FreeLangTypes.string);

      expect(child.lookup('x'), FreeLangTypes.i32);
      expect(child.lookup('y'), FreeLangTypes.string);
      expect(parent.lookup('y'), isNull);
    });
  });
}

