  void _setupMessageHandlers() {
    _webController.addJavaScriptHandler(
      handlerName: 'codeChanged',
      callback: (args) {
        if (args.isNotEmpty) {
          final code = args[0] as String;
          setState(() {
            _currentFile = _currentFile?.copyWith(content: code) ??
                CodeFile(name: 'untitled.fl', content: code);
            _isModified = true;
          });
          // 타입 검사 수행
          _performTypeCheck(code);
        }
      },
    );

    _webController.addJavaScriptHandler(
      handlerName: 'errorsDetected',
      callback: (args) {
        if (args.isNotEmpty) {
          final errorList = args[0] as List?;
          if (errorList != null) {
            final errors = errorList
                .map((e) {
                  final error = e as Map;
                  return EditorError(
                    line: error['line'] as int? ?? 0,
                    col: error['col'] as int? ?? 0,
                    message: error['message'] as String? ?? '',
                    severity: error['severity'] as String? ?? 'warning',
                  );
                })
                .toList();

            setState(() {
              _errors = errors;
              _errorCount = errors.where((e) => e.severity == 'error').length;
              _warningCount = errors.where((e) => e.severity == 'warning').length;
            });
          }
        }
      },
    );

    _webController.addJavaScriptHandler(
      handlerName: 'save',
      callback: (args) {
        _saveFile();
      },
    );
  }

  void _loadEditorHTML() {
    _webController.loadData(data: editorHTML);
  }

  void _initializeEditor() {
    if (_currentFile != null) {
      _webController.evaluateJavascript(
        'document.getElementById("editor").value = ${_currentFile!.content.replaceAll('"', '\\"')};',
      );
    }
  }

  void _handleAction(String action) {
    switch (action) {
      case 'save':
        _saveFile();
        break;
      case 'format':
        _formatCode();
        break;
      case 'upload':
        _uploadToHub();
        break;
      case 'new':
        _newFile();
        break;
      case 'open':
        _openFile();
        break;
    }
  }

  Future<void> _formatCode() async {
    try {
      await _getEditorContent();
      if (_currentFile == null) return;

      final formatted = CodeFormatter.format(_currentFile!.content);
      _currentFile = _currentFile!.copyWith(content: formatted);
      _isModified = true;

      // 에디터에 포맷된 코드 설정
      await _webController.evaluateJavascript(
        source: '''window.setEditorContent(${formatted.replaceAll('"', '\\"')});''',
      );

      _showMessage('코드 포맷팅 완료');
    } catch (e) {
      _showMessage('포맷팅 오류: $e', isError: true);
    }
  }

  Future<void> _uploadToHub() async {
    try {
      await _getEditorContent();
      if (_currentFile == null) return;

      final uploader = SnippetUploader();
      final suggestedTitle = uploader.suggestTitle(_currentFile!.content);
      final suggestedTags = uploader.suggestTags(_currentFile!.content);

      if (!mounted) return;

      // 업로드 다이얼로그
      final result = await showDialog<bool>(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('Hub에 업로드'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                decoration: const InputDecoration(
                  labelText: '제목',
                  hintText: suggestedTitle,
                ),
                controller: TextEditingController(text: suggestedTitle),
              ),
              const SizedBox(height: 12),
              Text(
                '태그: ${suggestedTags.join(", ")}',
                style: TextStyle(color: Colors.grey[600]),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context, false),
              child: const Text('취소'),
            ),
            TextButton(
              onPressed: () => Navigator.pop(context, true),
              child: const Text('업로드'),
            ),
          ],
        ),
      );

      if (result != true) return;

      // 업로드 실행
      final response = await uploader.uploadSnippet(
        code: _currentFile!.content,
        title: suggestedTitle,
        tags: suggestedTags,
      );

      if (response.success && mounted) {
        _showMessage('업로드 완료! 공유 링크: ${response.shareUrl}');
      }
    } catch (e) {
      _showMessage('업로드 오류: $e', isError: true);
    }
  }

  void _showMessage(String message, {bool isError = false}) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: isError ? Colors.red : Colors.green,
        duration: const Duration(seconds: 3),
      ),
    );
  }

  Future<void> _getEditorContent() async {
    try {
      final result = await _webController.evaluateJavascript(
        source: 'window.getEditorContent();',
      );
      if (result != null && result is String) {
        _currentFile = _currentFile?.copyWith(content: result) ??
            CodeFile(name: 'untitled.fl', content: result);
      }
    } catch (e) {
      print('[Editor] 콘텐츠 로드 오류: $e');
    }
  }

  Future<void> _runCode() async {
    // 에디터 내용을 현재 파일로 업데이트
    await _getEditorContent();

    if (_currentFile != null && _currentFile!.content.isNotEmpty) {
      // 오류 확인
      if (_errorCount > 0) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('⚠️ 오류가 있습니다. 수정 후 실행하세요'),
            backgroundColor: Colors.orange,
          ),
        );
        return;
      }

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('▶️ 실행: ${_currentFile!.name}'),
          duration: const Duration(seconds: 2),
        ),
      );

      // TODO: Runner 앱으로 딥링크
      // 향후: deeplink로 코드를 Runner에 전달
    }
  }

  Future<void> _runInRunner() async {
    await _getEditorContent();

    if (_currentFile == null || _currentFile!.content.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('코드를 입력하세요')),
      );
      return;
    }

    // TODO: 딥링크로 Runner 앱 열기
    // freelang://run?code=BASE64
    // final encoded = base64Encode(utf8.encode(_currentFile!.content));
    // launchUrl(Uri.parse('freelang://run?code=$encoded'));
  }

  void _showErrors() {
    if (_errors.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('✓ 오류가 없습니다')),
      );
      return;
    }

    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('오류 목록'),
        content: SizedBox(
          width: double.maxFinite,
          child: ListView.builder(
            itemCount: _errors.length,
            itemBuilder: (context, index) {
              final error = _errors[index];
              return ListTile(
                leading: Icon(
                  error.severity == 'error'
                      ? Icons.error
                      : Icons.warning,
                  color: error.severity == 'error'
                      ? Colors.red
                      : Colors.orange,
                  size: 20,
                ),
                title: Text(
                  error.message,
                  style: const TextStyle(fontSize: 12),
                ),
                subtitle: Text(
                  '${error.line + 1}:${error.col}',
                  style: TextStyle(
                    fontSize: 10,
                    color: Colors.grey[500],
                  ),
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('닫기'),
          ),
        ],
      ),
    );
  }

  Future<void> _saveFile() async {
    if (_currentFile == null) return;

    try {
      await widget.fileManager.saveFile(
        _currentFile!.name,
        _currentFile!.content,
      );

      setState(() => _isModified = false);

      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('저장되었습니다'),
          duration: Duration(seconds: 1),
        ),
      );
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('저장 실패: $e'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  void _newFile() {
    setState(() {
      _currentFile = CodeFile(
        name: 'new_file_${DateTime.now().millisecondsSinceEpoch}.fl',
        content: '',
      );
      _isModified = false;
    });
  }

  Future<void> _openFile() async {
    if (!mounted) return;

    final selectedFile = await Navigator.push<CodeFile>(
      context,
      MaterialPageRoute(
        builder: (_) => FilesScreen(fileManager: widget.fileManager),
      ),
    );

    if (selectedFile != null && mounted) {
      try {
        final content = await widget.fileManager.readFile(selectedFile.path!);
        setState(() {
          _currentFile = CodeFile(
            name: selectedFile.name,
            content: content,
            path: selectedFile.path,
          );
          _isModified = false;
        });
        _initializeEditor();
      } catch (e) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('파일 로드 실패: $e')),
        );
      }
    }
  }
}

