     4→import 'type_system.dart';
     5→
     6→/// IDE 인라인 타입 힌트 표시용 데이터 클래스
     7→class TypeHint {
     8→  final int line;
     9→  final int column;
    10→  final String variableName;
    11→  final FreeLangType inferredType;
    12→
    13→  TypeHint({
    14→    required this.line,
    15→    required this.column,
    16→    required this.variableName,
    17→    required this.inferredType,
    18→  });
    19→
    20→  @override
    21→  String toString() =>
    22→      '$variableName: ${inferredType.name} (line $line:$column)';
    23→}
    24→
    25→/// 타입 추론 엔진 (정적 메서드 기반)
    26→class TypeInferrer {
    27→  /// 코드에서 추론 가능한 모든 타입 힌트 추출
    28→  static List<TypeHint> inferAll(String code) {
    29→    final hints = <TypeHint>[];
    30→    final lines = code.split('\n');
    31→
    32→    for (int i = 0; i < lines.length; i++) {
    33→      final line = lines[i];
    34→      final variableMatch =
    35→          RegExp(r'let\s+(\w+)\s*(?::|\s*=)').firstMatch(line);
    36→
    37→      if (variableMatch != null) {
    38→        final varName = variableMatch.group(1)!;
    39→        final column = variableMatch.start(1);
    40→
    41→        // 타입 주석이 있으면 스킵
    42→        if (line.contains('let $varName:')) {
    43→          continue;
    44→        }
    45→
    46→        // 할당값에서 타입 추론
    47→        final value = _extractAssignmentValue(line);
    48→        if (value != null) {
    49→          final inferredType = inferLiteral(value);
    50→          if (inferredType != FreeLangTypes.unknown) {
    51→            hints.add(TypeHint(
    52→              line: i,
    53→              column: column,
    54→              variableName: varName,
    55→              inferredType: inferredType,
    56→            ));
    57→          }
    58→        }
    59→      }
    60→    }
    61→
    62→    return hints;
    63→  }
    64→
    65→  /// 단일 표현식의 타입 추론
    66→  static FreeLangType inferExpression(String expr, TypeEnvironment env) {
    67→    final trimmed = expr.trim();
    68→
    69→    // 리터럴 타입 추론
    70→    final literalType = inferLiteral(trimmed);
    71→    if (literalType != FreeLangTypes.unknown) {
    72→      return literalType;
    73→    }
    74→
    75→    // 변수 타입 추론
    76→    final varType = env.lookup(trimmed);
    77→    if (varType != null) {
    78→      return varType;
    79→    }
    80→
    81→    // 이진 연산 추론 (간단한 패턴)
    82→    for (final op in ['+', '-', '*', '/', '>', '<', '==', '!=', '&&', '||']) {
    83→      if (trimmed.contains(op)) {
    84→        final parts = trimmed.split(op);
    85→        if (parts.length == 2) {
    86→          final leftType = inferExpression(parts[0].trim(), env);
    87→          final rightType = inferExpression(parts[1].trim(), env);
    88→          return inferBinaryOp(leftType, op, rightType);
    89→        }
    90→      }
    91→    }
    92→
    93→    return FreeLangTypes.unknown;
    94→  }
    95→
    96→  /// 리터럴 값의 타입 추론
    97→  /// "10" -> i32, "3.14" -> f64, '"hello"' -> string, "true"/"false" -> bool
    98→  static FreeLangType inferLiteral(String value) {
    99→    final trimmed = value.trim();
   100→
   101→    // 문자열 리터럴
   102→    if ((trimmed.startsWith('"') && trimmed.endsWith('"')) ||
   103→        (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
   104→      return FreeLangTypes.string;
   105→    }
   106→
   107→    // bool 리터럴
   108→    if (trimmed == 'true' || trimmed == 'false') {
   109→      return FreeLangTypes.bool_;
   110→    }
   111→
   112→    // nil 리터럴
   113→    if (trimmed == 'nil') {
   114→      return FreeLangTypes.nil;
   115→    }
   116→
   117→    // 실수 리터럴 (점 포함)
   118→    if (RegExp(r'^-?\d+\.\d+$').hasMatch(trimmed)) {
   119→      // 명시적으로 지수 표기법이 없으면 f64
   120→      if (trimmed.endsWith('f')) {
   121→        return FreeLangTypes.f32;
   122→      }
   123→      return FreeLangTypes.f64;
   124→    }
   125→
   126→    // 정수 리터럴
   127→    if (RegExp(r'^-?\d+$').hasMatch(trimmed)) {
   128→      // 명시적 타입 지정이 없으면 i32 (기본값)
   129→      if (trimmed.endsWith('L')) {
   130→        return FreeLangTypes.i64;
   131→      }
   132→      return FreeLangTypes.i32;
   133→    }
   134→
   135→    return FreeLangTypes.unknown;
   136→  }
   137→
   138→  /// 이진 연산 결과 타입 추론
   139→  /// i32 + i32 -> i32, string + string -> string, i32 > i32 -> bool, 등
   140→  static FreeLangType inferBinaryOp(
   141→    FreeLangType left,
   142→    String op,
   143→    FreeLangType right,
   144→  ) {
   145→    // 비교 연산자는 항상 bool
   146→    if (['>', '<', '>=', '<=', '==', '!=', '&&', '||'].contains(op)) {
   147→      // 하지만 양쪽 타입이 호환 가능해야 함
   148→      if (left.isAssignableTo(right) || right.isAssignableTo(left)) {
   149→        return FreeLangTypes.bool_;
   150→      }
   151→      return FreeLangTypes.unknown;
   152→    }
   153→
   154→    // 산술 연산: 양쪽 타입이 같아야 함
   155→    if (['+', '-', '*', '/'].contains(op)) {
   156→      if (left is PrimitiveType && right is PrimitiveType) {
   157→        if (left.name == right.name) {
   158→          return left; // i32 + i32 = i32, f64 + f64 = f64, string + string = string
   159→        }
   160→      }
   161→    }
   162→
   163→    return FreeLangTypes.unknown;
   164→  }
   165→
   166→  /// 할당문에서 값 추출 (간단한 파싱)
   167→  static String? _extractAssignmentValue(String line) {
   168→    // 'let x = value' 패턴
   169→    final match = RegExp(r'let\s+\w+\s*=\s*(.+)$').firstMatch(line);
   170→    if (match != null) {
   171→      return match.group(1)?.trim();
   172→    }
   173→    return null;
   174→  }
   175→}
