## Step 2: `apps/ide/lib/services/trait_system.dart` (~280줄, 신규)

### 트레이트/인터페이스 시스템

```dart
// 트레이트 메서드 시그니처
class TraitMethod {
  final String name;
  final FunctionType signature;
}

// 트레이트 정의
class TraitDefinition {
  final String name;
  final List<TraitMethod> methods;
  bool hasMethod(String methodName);
}

// 트레이트 구현체 레지스트리
class TraitRegistry {
  void registerTrait(TraitDefinition trait);
  void registerImpl(String typeName, String traitName);
  bool implements_(String typeName, String traitName);
  TraitDefinition? getTrait(String name);
  List<String> getImplementedTraits(String typeName);

  // 기본 내장 트레이트
  static TraitRegistry withBuiltins();
  // Printable: fn toString() -> string
  // Comparable: fn compareTo(other) -> i32
  // Serializable: fn serialize() -> string
}

// 타입 시스템에 추가: TraitBoundType (트레이트 바운드가 있는 제네릭)
class TraitBoundType extends FreeLangType {
  final TypeParameter param;
  final TraitRegistry registry;
}

// 트레이트 검사기
class TraitChecker {
  static List<Diagnostic> check(String code, TraitRegistry registry);
  // 'impl Printable for MyType'에서 필수 메서드 구현 여부 검사
  // 트레이트 바운드 만족 여부 검사
}
