// Result<T, E> 타입
class ResultType extends FreeLangType {
  final FreeLangType okType;
  final FreeLangType errType;
  String get name => 'Result<${okType.name},${errType.name}>';
  bool isAssignableTo(FreeLangType other);
}

// Option<T> 타입 (OptionType 확장)
// type_system.dart의 OptionType 재사용, 추가 로직만 여기에

// 에러 핸들링 검사기
class ErrorHandlingChecker {
  static List<Diagnostic> check(String code);

  // try { ... } catch(e) { ... } 구문 검사
  static List<Diagnostic> _checkTryCatch(List<String> lines);
  // ? 연산자 사용 검사: Result 타입에만 사용 가능
  static List<Diagnostic> _checkUnwrapOperator(List<String> lines, TypeEnvironment env);
  // Diagnostic 코드: 'invalid-unwrap', 'uncaught-error', 'result-unused'
}

// 에러 핸들링 추론 확장
class ErrorInferrer {
  static FreeLangType? inferTryCatch(String tryBlock, TypeEnvironment env);
  static FreeLangType? inferUnwrap(FreeLangType resultType);
  // Result<i32, string>? -> i32 (성공 시)
}
```

