## Step 4: `apps/ide/lib/services/pattern_matcher.dart` (~300줄, 신규)

### 패턴 매칭 고급 시스템

```dart
// 패턴 타입 계층
abstract class Pattern {
  bool matches(String value);
  Map<String, FreeLangType> bindings(TypeEnvironment env);
}

class LiteralPattern extends Pattern { final String value; }
// match x { 42 => ..., "hello" => ... }

class WildcardPattern extends Pattern { }
// match x { _ => ... }

class BindingPattern extends Pattern { final String name; }
// match x { n => ... }  // n에 x를 바인딩

class TuplePattern extends Pattern { final List<Pattern> elements; }
// let (a, b) = pair

class ConstructorPattern extends Pattern {
  final String name;        // 'Some', 'Ok', 'Err'
  final List<Pattern> args;
}
// match opt { Some(x) => ..., None => ... }

class GuardPattern extends Pattern {
  final Pattern inner;
  final String guard;
}
// match x { n if n > 0 => ... }

// 매치 암(arm) - 패턴 + 표현식
class MatchArm {
  final Pattern pattern;
  final String body;
}

// 패턴 매칭 검사기
class PatternMatcher {
  static List<Diagnostic> check(String code, TypeEnvironment env);
