// generics_system.dart - 제네릭 타입 파라미터 및 인스턴스화 시스템

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 제네릭 타입 파라미터 (T, K, V, Element 등)
class TypeParameter {
  final String name; // 'T', 'K', 'V', 'Element'
  final List<String> bounds; // ['Comparable', 'Serializable'] - 트레이트 바운드

  TypeParameter({
    required this.name,
    this.bounds = const [],
  });

  @override
  String toString() {
    if (bounds.isEmpty) return name;
    return '$name: ${bounds.join(" + ")}';
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TypeParameter &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          bounds == other.bounds;

  @override
  int get hashCode => Object.hash(name, bounds);
}

/// 제네릭 함수 타입: fn<T>(item: T) -> T
class GenericFunctionType extends FreeLangType {
  final List<TypeParameter> typeParams;
  final FunctionType baseType;

  GenericFunctionType({
    required this.typeParams,
    required this.baseType,
  });

  @override
  String get name {
    final params = typeParams.join(', ');
    return 'fn<$params>(${baseType.paramTypes.map((t) => t.name).join(', ')}) -> ${baseType.returnType.name}';
  }

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is GenericFunctionType) {
      if (typeParams.length != other.typeParams.length) return false;
      return baseType.isAssignableTo(other.baseType);
    }
    return false;
  }

  /// 타입 바인딩으로 제네릭 인스턴스화
  /// fn<T>(T) -> T에서 T=i32를 주면 fn(i32) -> i32
  FreeLangType instantiate(Map<String, FreeLangType> bindings) {
    // 간단히 baseType 반환 (실제로는 타입 파라미터 치환 필요)
    return baseType;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is GenericFunctionType &&
          runtimeType == other.runtimeType &&
          typeParams == other.typeParams &&
          baseType == other.baseType;

  @override
  int get hashCode => Object.hash(typeParams, baseType);
}

/// 제네릭 인스턴스: Array<i32>, Map<string, i32>, Option<string>
class GenericInstance extends FreeLangType {
  final String baseName; // 'Array', 'Map', 'Option', 'Result'
  final List<FreeLangType> args; // [i32], [string, i32], [string]

  GenericInstance({
    required this.baseName,
    required this.args,
  });

  @override
  String get name {
    final argNames = args.map((a) => a.name).join(', ');
    return '$baseName<$argNames>';
  }

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is GenericInstance) {
      if (baseName != other.baseName || args.length != other.args.length) {
        return false;
      }
      // 모든 타입 인자가 호환 가능해야 함
      for (int i = 0; i < args.length; i++) {
        if (!args[i].isAssignableTo(other.args[i])) {
          return false;
        }
      }
      return true;
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is GenericInstance &&
          runtimeType == other.runtimeType &&
          baseName == other.baseName &&
          args == other.args;

  @override
  int get hashCode => Object.hash(baseName, args);
}

/// 제네릭 파서
class GenericsParser {
  /// 타입 파라미터 파싱: 'T' -> TypeParameter(name:'T'), 'T: Comparable' -> bounds 포함
  static TypeParameter? parseTypeParam(String text) {
    final trimmed = text.trim();

    // 'T: Comparable' 형식
    if (trimmed.contains(':')) {
      final parts = trimmed.split(':');
      final name = parts[0].trim();
      final boundsStr = parts[1].trim();
      final bounds = boundsStr.split('+').map((b) => b.trim()).toList();

      if (!RegExp(r'^[A-Z]$').hasMatch(name)) {
        return null; // 타입 파라미터는 대문자 한 글자
      }

      return TypeParameter(name: name, bounds: bounds);
    }

    // 단순 'T' 형식
    if (RegExp(r'^[A-Z]$').hasMatch(trimmed)) {
      return TypeParameter(name: trimmed);
    }

    return null;
  }

  /// 제네릭 타입 파싱: 'Array<i32>' -> GenericInstance('Array', [i32])
  static GenericInstance? parseGenericType(String text) {
    final trimmed = text.trim();

    // 'Name<Args>' 패턴 매칭
    final match = RegExp(r'^(\w+)<(.+)>$').firstMatch(trimmed);
    if (match == null) return null;

    final baseName = match.group(1)!;
    final argsStr = match.group(2)!;

    // 인자들을 쉼표로 분리
    final argStrs = argsStr.split(',').map((s) => s.trim());
    final args = <FreeLangType>[];

    for (final argStr in argStrs) {
      // 중첩된 제네릭 재귀 파싱
      final nested = parseGenericType(argStr);
      if (nested != null) {
        args.add(nested);
        continue;
      }

      // 기본 타입
      final basic = FreeLangTypes.fromString(argStr);
      if (basic != null) {
        args.add(basic);
        continue;
      }

      return null; // 알 수 없는 타입
    }

    return GenericInstance(baseName: baseName, args: args);
  }

  /// 제네릭 함수 선언 파싱: 'fn<T, U>(a: T, b: U) -> T' 검증
  static List<Diagnostic> checkGenericUsage(String code) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // 제네릭 함수 선언: fn<T, ...>(...) -> ...
      final fnMatch = RegExp(r'fn<([^>]+)>\s*\(([^)]*)\)\s*->\s*(\w+)')
          .firstMatch(line);

      if (fnMatch != null) {
        final typeParamStr = fnMatch.group(1)!;
        final paramsStr = fnMatch.group(2)!;
        final returnStr = fnMatch.group(3)!;

        // 타입 파라미터 파싱
        final paramStrs = typeParamStr.split(',').map((s) => s.trim());
        final typeParams = <TypeParameter>[];

        for (final paramStr in paramStrs) {
          final param = parseTypeParam(paramStr);
          if (param == null) {
            diagnostics.add(Diagnostic(
              line: i,
              column: fnMatch.start(1),
              message: "Invalid type parameter: '$paramStr'",
              severity: DiagnosticSeverity.error,
              code: 'invalid-type-param',
            ));
            continue;
          }
          typeParams.add(param);
        }

        // 반환 타입이 선언된 타입 파라미터 중 하나여야 함 (간단한 검증)
        final declaredNames = typeParams.map((p) => p.name).toList();
        if (!declaredNames.contains(returnStr) &&
            FreeLangTypes.fromString(returnStr) == null) {
          diagnostics.add(Diagnostic(
            line: i,
            column: fnMatch.start(3),
            message:
                "Return type '$returnStr' must be a type parameter or built-in type",
            severity: DiagnosticSeverity.warning,
            code: 'invalid-return-type',
          ));
        }
      }
    }

    return diagnostics;
  }
}

