// trait_system.dart - 트레이트/인터페이스 시스템

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 트레이트 메서드 시그니처
class TraitMethod {
  final String name;
  final FunctionType signature;

  TraitMethod({
    required this.name,
    required this.signature,
  });

  @override
  String toString() => '$name: $signature';

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TraitMethod &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          signature == other.signature;

  @override
  int get hashCode => Object.hash(name, signature);
}

/// 트레이트 정의 (메서드 시그니처 모음)
class TraitDefinition {
  final String name;
  final List<TraitMethod> methods;

  TraitDefinition({
    required this.name,
    required this.methods,
  });

  /// 트레이트에 특정 메서드가 있는지 확인
  bool hasMethod(String methodName) {
    return methods.any((m) => m.name == methodName);
  }

  /// 트레이트의 모든 메서드 이름
  List<String> getMethodNames() {
    return methods.map((m) => m.name).toList();
  }

  @override
  String toString() {
    final methodsStr = methods.map((m) => '  ${m.name}()').join('\n');
    return 'trait $name {\n$methodsStr\n}';
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TraitDefinition &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          methods == other.methods;

  @override
  int get hashCode => Object.hash(name, methods);
}

/// 트레이트 레지스트리 - 트레이트 정의 및 구현 관리
class TraitRegistry {
  final Map<String, TraitDefinition> _traits = {};
  final Map<String, Set<String>> _impls = {}; // typeName -> Set<traitName>

  /// 트레이트 등록
  void registerTrait(TraitDefinition trait) {
    _traits[trait.name] = trait;
  }

  /// 특정 타입이 특정 트레이트를 구현했음을 등록
  void registerImpl(String typeName, String traitName) {
    _impls.putIfAbsent(typeName, () => {}).add(traitName);
  }

  /// 특정 타입이 특정 트레이트를 구현했는지 확인
  bool implements_(String typeName, String traitName) {
    return _impls[typeName]?.contains(traitName) ?? false;
  }

  /// 트레이트 정의 조회
  TraitDefinition? getTrait(String name) {
    return _traits[name];
  }

  /// 특정 타입이 구현한 모든 트레이트 반환
  List<String> getImplementedTraits(String typeName) {
    return (_impls[typeName] ?? {}).toList();
  }

  /// 모든 등록된 트레이트 반환
  List<TraitDefinition> getAllTraits() {
    return _traits.values.toList();
  }

  /// 내장 트레이트를 포함한 레지스트리 생성
  static TraitRegistry withBuiltins() {
    final registry = TraitRegistry();

    // Printable: fn toString() -> string
    registry.registerTrait(TraitDefinition(
      name: 'Printable',
      methods: [
        TraitMethod(
          name: 'toString',
          signature: FunctionType(
            paramTypes: [],
            returnType: FreeLangTypes.string,
          ),
        ),
      ],
    ));

    // Comparable: fn compareTo(other) -> i32
    registry.registerTrait(TraitDefinition(
      name: 'Comparable',
      methods: [
        TraitMethod(
          name: 'compareTo',
          signature: FunctionType(
            paramTypes: [FreeLangTypes.unknown], // self 타입 생략
            returnType: FreeLangTypes.i32,
          ),
        ),
      ],
    ));

    // Serializable: fn serialize() -> string
    registry.registerTrait(TraitDefinition(
      name: 'Serializable',
      methods: [
        TraitMethod(
          name: 'serialize',
          signature: FunctionType(
            paramTypes: [],
            returnType: FreeLangTypes.string,
          ),
        ),
      ],
    ));

    return registry;
  }
}

/// 트레이트 바운드가 있는 제네릭 타입
class TraitBoundType extends FreeLangType {
  final String paramName; // 'T'
  final String traitName; // 'Comparable'

  TraitBoundType({
    required this.paramName,
    required this.traitName,
  });

  @override
  String get name => '$paramName: $traitName';

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is TraitBoundType) {
      return paramName == other.paramName && traitName == other.traitName;
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TraitBoundType &&
          runtimeType == other.runtimeType &&
          paramName == other.paramName &&
          traitName == other.traitName;

  @override
  int get hashCode => Object.hash(paramName, traitName);
}

/// 트레이트 검사기
class TraitChecker {
  /// 코드의 트레이트 관련 오류 검사
  static List<Diagnostic> check(
    String code,
    TraitRegistry registry,
  ) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    // impl Trait for Type { ... } 검사
    diagnostics.addAll(_checkTraitImpl(lines, registry));

    // 트레이트 바운드 검사
    diagnostics.addAll(_checkTraitBounds(lines, registry));

    return diagnostics;
  }

  /// impl TraitName for TypeName 검사
  static List<Diagnostic> _checkTraitImpl(
    List<String> lines,
    TraitRegistry registry,
  ) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // impl Trait for Type { ... }
      final match = RegExp(r'impl\s+(\w+)\s+for\s+(\w+)\s*\{')
          .firstMatch(line);

      if (match != null) {
        final traitName = match.group(1)!;
        final typeName = match.group(2)!;

        // 트레이트 존재 확인
        final trait = registry.getTrait(traitName);
        if (trait == null) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start(1),
            message: "Unknown trait '$traitName'",
            severity: DiagnosticSeverity.error,
            code: 'unknown-trait',
          ));
          continue;
        }

        // 필수 메서드 구현 확인 (간단히 구현 등록만)
        registry.registerImpl(typeName, traitName);
      }
    }

    return diagnostics;
  }

  /// 트레이트 바운드 만족 확인
  static List<Diagnostic> _checkTraitBounds(
    List<String> lines,
    TraitRegistry registry,
  ) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // fn<T: Comparable>(x: T) 형식 검사
      final match = RegExp(r'fn<(\w+):\s*(\w+)>').firstMatch(line);
      if (match != null) {
        final paramName = match.group(1)!;
        final traitName = match.group(2)!;

        // 트레이트 존재 확인
        if (registry.getTrait(traitName) == null) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start(2),
            message: "Unknown trait '$traitName' in type bound",
            severity: DiagnosticSeverity.error,
            code: 'unknown-trait',
          ));
        }
      }
    }

    return diagnostics;
  }
}

