// error_handling.dart - Result/Option 에러 핸들링 시스템

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// Result<T, E> 타입 - 성공 또는 에러를 나타냄
class ResultType extends FreeLangType {
  final FreeLangType okType;
  final FreeLangType errType;

  ResultType({
    required this.okType,
    required this.errType,
  });

  @override
  String get name => 'Result<${okType.name},${errType.name}>';

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is ResultType) {
      return okType.isAssignableTo(other.okType) &&
          errType.isAssignableTo(other.errType);
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ResultType &&
          runtimeType == other.runtimeType &&
          okType == other.okType &&
          errType == other.errType;

  @override
  int get hashCode => Object.hash(okType, errType);
}

/// 에러 핸들링 검사기
class ErrorHandlingChecker {
  /// 코드의 에러 핸들링 관련 오류 검사
  static List<Diagnostic> check(
    String code,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    // try-catch 구문 검사
    diagnostics.addAll(_checkTryCatch(lines));

    // ? 연산자 사용 검사
    diagnostics.addAll(_checkUnwrapOperator(lines, env));

    return diagnostics;
  }

  /// try { ... } catch(e: type) { ... } 검사
  static List<Diagnostic> _checkTryCatch(List<String> lines) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // try { ... }
      if (line.contains('try')) {
        final tryMatch = RegExp(r'try\s*\{').firstMatch(line);
        if (tryMatch != null) {
          // catch 블록 확인 (다음 줄들에서)
          bool hasCatch = false;
          for (int j = i + 1; j < lines.length && j < i + 10; j++) {
            if (lines[j].contains('catch')) {
              hasCatch = true;
              break;
            }
            if (lines[j].contains('}') && !lines[j].contains('catch')) {
              break;
            }
          }

          if (!hasCatch) {
            diagnostics.add(Diagnostic(
              line: i,
              column: tryMatch.start(),
              message: "try block must be followed by catch",
              severity: DiagnosticSeverity.warning,
              code: 'uncaught-error',
            ));
          }
        }
      }

      // catch(e: type) 형식 검사
      final catchMatch = RegExp(r'catch\s*\(\s*\w+\s*:\s*(\w+)\s*\)')
          .firstMatch(line);
      if (catchMatch != null) {
        final errorType = catchMatch.group(1)!;
        // 에러 타입이 유효한지 확인
        if (errorType != 'string' && !RegExp(r'^[A-Z]').hasMatch(errorType)) {
          diagnostics.add(Diagnostic(
            line: i,
            column: catchMatch.start(1),
            message: "Error type should be 'string' or a custom error type",
            severity: DiagnosticSeverity.information,
            code: 'error-type-suggestion',
          ));
        }
      }
    }

    return diagnostics;
  }

  /// ? 연산자 사용 검사 (Result 타입에만 가능)
  static List<Diagnostic> _checkUnwrapOperator(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // value? 또는 value?. 형식
      final match = RegExp(r'(\w+)\?').firstMatch(line);
      if (match != null) {
        final varName = match.group(1)!;

        // 변수의 타입 조회
        final varType = env.lookup(varName);
        if (varType != null && varType is! ResultType) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start(),
            message:
                "? operator can only be used with Result type, got ${varType.name}",
            severity: DiagnosticSeverity.error,
            code: 'invalid-unwrap',
          ));
        }
      }
    }

    return diagnostics;
  }
}

/// 에러 핸들링 타입 추론
class ErrorInferrer {
  /// try-catch 표현식의 타입 추론
  /// try { T } catch(e) { E } -> T (모든 경로에서 T를 반환해야 함)
  static FreeLangType? inferTryCatch(
    String tryBlock,
    TypeEnvironment env,
  ) {
    // 간단히 try 블록의 마지막 표현식 타입만 반환
    final lines = tryBlock.split('\n');
    if (lines.isNotEmpty) {
      // 실제로는 try와 catch 블록의 타입이 일치해야 함
      final lastLine = lines.last.trim();
      if (lastLine.isEmpty || lastLine == '}') {
        return FreeLangTypes.nil;
      }
    }
    return FreeLangTypes.unknown;
  }

  /// ? 연산자 사용 시 추론 결과 타입
  /// Result<i32, string>? -> i32 (unwrap to ok type)
  static FreeLangType? inferUnwrap(FreeLangType resultType) {
    if (resultType is ResultType) {
      return resultType.okType;
    }
    return null;
  }

  /// Result 리터럴 추론: Ok(value), Err(msg)
  static FreeLangType inferResultLiteral(
    String literal,
    TypeEnvironment env,
  ) {
    if (literal.startsWith('Ok(')) {
      // Ok(value) -> Result<T, unknown>
      return ResultType(
        okType: FreeLangTypes.unknown,
        errType: FreeLangTypes.unknown,
      );
    }
    if (literal.startsWith('Err(')) {
      // Err(msg) -> Result<unknown, E>
      return ResultType(
        okType: FreeLangTypes.unknown,
        errType: FreeLangTypes.unknown,
      );
    }
    return FreeLangTypes.unknown;
  }
}

