// pattern_matcher.dart - 고급 패턴 매칭 시스템

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 패턴 추상 클래스
abstract class Pattern {
  /// 이 패턴이 주어진 값과 매치되는지 확인
  bool matches(String value);

  /// 패턴이 바인드하는 변수들의 타입
  Map<String, FreeLangType> bindings(TypeEnvironment env);
}

/// 리터럴 패턴: 42, "hello", true
class LiteralPattern extends Pattern {
  final String value;

  LiteralPattern(this.value);

  @override
  bool matches(String value) => this.value == value;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) => {};

  @override
  String toString() => value;
}

/// 와일드카드 패턴: _
class WildcardPattern extends Pattern {
  @override
  bool matches(String value) => true;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) => {};

  @override
  String toString() => '_';
}

/// 바인딩 패턴: x, n (변수에 값을 바인드)
class BindingPattern extends Pattern {
  final String name;
  final FreeLangType? expectedType; // 선택적 타입 주석

  BindingPattern(this.name, [this.expectedType]);

  @override
  bool matches(String value) => true;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    return {name: expectedType ?? FreeLangTypes.unknown};
  }

  @override
  String toString() => name;
}

/// 튜플 패턴: (a, b), (x, y, z)
class TuplePattern extends Pattern {
  final List<Pattern> elements;

  TuplePattern(this.elements);

  @override
  bool matches(String value) => true; // 간단한 구현

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    final result = <String, FreeLangType>{};
    for (final elem in elements) {
      result.addAll(elem.bindings(env));
    }
    return result;
  }

  @override
  String toString() => '(${elements.join(', ')})';
}

/// 생성자 패턴: Some(x), Ok(value), Err(msg), None
class ConstructorPattern extends Pattern {
  final String name; // 'Some', 'Ok', 'Err', 'None'
  final List<Pattern> args;

  ConstructorPattern(this.name, [this.args = const []]);

  @override
  bool matches(String value) {
