  static bool isExhaustive(List<MatchArm> arms, FreeLangType type) {
    // 와일드카드 또는 기본값이 있으면 완전
    final hasWildcard =
        arms.any((arm) => arm.pattern is WildcardPattern);
    if (hasWildcard) return true;

    // Option<T>의 경우: Some(x), None 필요
    if (type is OptionType) {
      final hasConstructor = arms.any(
        (arm) =>
            arm.pattern is ConstructorPattern &&
            (arm.pattern as ConstructorPattern).name == 'Some',
      );
      final hasNone = arms.any(
        (arm) =>
            arm.pattern is ConstructorPattern &&
            (arm.pattern as ConstructorPattern).name == 'None',
      );
      return hasConstructor && hasNone;
    }

    // 기본값으로 불완전 처리
    return false;
  }

  /// match 표현식의 결과 타입 추론 (모든 암의 타입이 일치해야 함)
  static FreeLangType inferMatchType(
    List<MatchArm> arms,
    TypeEnvironment env,
  ) {
    if (arms.isEmpty) {
      return FreeLangTypes.unknown;
    }

    // 간단히 첫 암의 타입 반환
    // 실제로는 모든 암의 타입이 호환되어야 함
    return FreeLangTypes.unknown;
  }

  /// match 패턴 파싱
  static Pattern? parsePattern(String text) {
    final trimmed = text.trim();

    // 와일드카드: _
    if (trimmed == '_') {
      return WildcardPattern();
    }

    // 생성자 패턴: Some(x), Ok(v), Err(msg), None
    if (trimmed.contains('(')) {
      final match = RegExp(r'^(\w+)\(([^)]*)\)$').firstMatch(trimmed);
      if (match != null) {
        final name = match.group(1)!;
        final argsStr = match.group(2)!.trim();

        if (argsStr.isEmpty) {
          return ConstructorPattern(name);
        }

        final args = argsStr.split(',').map((s) {
          final pattern = parsePattern(s.trim());
          return pattern ?? LiteralPattern(s.trim());
        }).toList();

        return ConstructorPattern(name, args);
      }
    }

    // 튜플 패턴: (a, b)
    if (trimmed.startsWith('(') && trimmed.endsWith(')')) {
      final inner = trimmed.substring(1, trimmed.length - 1);
      final elements = inner.split(',').map((s) {
        final pattern = parsePattern(s.trim());
        return pattern ?? WildcardPattern();
      }).toList();
      return TuplePattern(elements);
    }

    // 가드 패턴: n if n > 0
    if (trimmed.contains(' if ')) {
      final parts = trimmed.split(' if ');
      final innerPattern = parsePattern(parts[0].trim());
      if (innerPattern != null) {
        return GuardPattern(innerPattern, parts[1].trim());
      }
    }

    // 바인딩 패턴: x, n, item
    if (RegExp(r'^\w+$').hasMatch(trimmed)) {
      return BindingPattern(trimmed);
    }

    // 리터럴 패턴: 42, "hello"
    return LiteralPattern(trimmed);
  }

  /// match 표현식 파싱 및 검사
  static List<Diagnostic> checkMatchExpression(
    List<String> lines,
    int startLine,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];
    final arms = <MatchArm>[];

    int braceCount = 0;
    int endLine = startLine;

    // match 블록 끝 찾기
    for (int i = startLine; i < lines.length; i++) {
      braceCount += '{'.allMatches(lines[i]).length;
      braceCount -= '}'.allMatches(lines[i]).length;
      if (braceCount == 0) {
        endLine = i;
        break;
      }
    }

    // 각 암 파싱
    for (int i = startLine + 1; i < endLine; i++) {
      final line = lines[i];
      final armMatch = RegExp(r'(\w+.*?)\s*=>\s*(.+)').firstMatch(line);

      if (armMatch != null) {
        final patternStr = armMatch.group(1)!;
        final bodyStr = armMatch.group(2)!;

        final pattern = parsePattern(patternStr);
        if (pattern != null) {
          arms.add(MatchArm(pattern, bodyStr));
        }
      }
    }

    // 완전성 확인
    // 불완전한 match 경고
    if (!_hasWildcard(arms) && arms.isNotEmpty) {
      diagnostics.add(Diagnostic(
        line: startLine,
        column: 0,
        message: "Non-exhaustive match expression (not all cases covered)",
        severity: DiagnosticSeverity.warning,
        code: 'non-exhaustive-match',
      ));
    }

    return diagnostics;
  }

  static bool _hasWildcard(List<MatchArm> arms) {
    return arms.any((arm) => arm.pattern is WildcardPattern);
  }
}

