// advanced_features_test.dart - Phase 9 고급 기능 테스트 (25개)

import 'package:flutter_test/flutter_test.dart';
import 'package:ide/services/type_system.dart';
import 'package:ide/services/generics_system.dart';
import 'package:ide/services/trait_system.dart';
import 'package:ide/services/error_handling.dart';
import 'package:ide/services/pattern_matcher.dart';
import 'package:ide/services/lsp_features.dart' show DiagnosticSeverity;

void main() {
  group('제네릭 시스템 (Generics)', () {
    test('Test 1: TypeParameter 파싱 - 단순', () {
      final param = GenericsParser.parseTypeParam('T');
      expect(param, isNotNull);
      expect(param!.name, 'T');
      expect(param.bounds, isEmpty);
    });

    test('Test 2: TypeParameter 파싱 - 트레이트 바운드', () {
      final param = GenericsParser.parseTypeParam('T: Comparable');
      expect(param, isNotNull);
      expect(param!.name, 'T');
      expect(param.bounds, contains('Comparable'));
    });

    test('Test 3: GenericInstance 파싱 - Array<i32>', () {
      final instance = GenericsParser.parseGenericType('Array<i32>');
      expect(instance, isNotNull);
      expect(instance!.baseName, 'Array');
      expect(instance.args.length, 1);
      expect(instance.args[0], FreeLangTypes.i32);
    });

    test('Test 4: GenericInstance - Map<string, i32>', () {
      final instance = GenericsParser.parseGenericType('Map<string, i32>');
      expect(instance, isNotNull);
      expect(instance!.baseName, 'Map');
      expect(instance.args.length, 2);
      expect(instance.args[0], FreeLangTypes.string);
      expect(instance.args[1], FreeLangTypes.i32);
    });

    test('Test 5: GenericFunctionType 인스턴스화', () {
      final fn = GenericFunctionType(
        typeParams: [TypeParameter(name: 'T')],
        baseType: FunctionType(
          paramTypes: [FreeLangTypes.unknown],
          returnType: FreeLangTypes.unknown,
        ),
      );
      expect(fn.name, contains('fn<T>'));
    });

    test('Test 6: 제네릭 사용 검사 - 올바른 형식', () {
      const code = 'fn<T>(item: T) -> T { item }';
      final diagnostics = GenericsParser.checkGenericUsage(code);
      expect(
        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
        true,
      );
    });
  });

  group('트레이트 시스템 (Traits)', () {
    test('Test 7: 트레이트 등록 및 조회', () {
      final registry = TraitRegistry();
      final trait = TraitDefinition(
        name: 'Debug',
        methods: [
          TraitMethod(
            name: 'debug',
            signature: FunctionType(
              paramTypes: [],
              returnType: FreeLangTypes.string,
            ),
          ),
        ],
      );

      registry.registerTrait(trait);
      expect(registry.getTrait('Debug'), isNotNull);
      expect(registry.getTrait('Debug')!.name, 'Debug');
    });

    test('Test 8: 트레이트 구현 등록', () {
      final registry = TraitRegistry();
      registry.registerImpl('MyType', 'Debug');
      expect(registry.implements_('MyType', 'Debug'), true);
      expect(registry.implements_('OtherType', 'Debug'), false);
    });

    test('Test 9: 내장 트레이트 (Printable, Comparable)', () {
      final registry = TraitRegistry.withBuiltins();
      expect(registry.getTrait('Printable'), isNotNull);
      expect(registry.getTrait('Comparable'), isNotNull);
      expect(registry.getTrait('Serializable'), isNotNull);
    });

    test('Test 10: 내장 트레이트 메서드 확인', () {
      final registry = TraitRegistry.withBuiltins();
      final printable = registry.getTrait('Printable')!;
      expect(printable.hasMethod('toString'), true);

      final comparable = registry.getTrait('Comparable')!;
      expect(comparable.hasMethod('compareTo'), true);
    });

    test('Test 11: 트레이트 구현 검사 - 올바름', () {
      const code = 'impl Printable for MyType { fn toString() { "debug" } }';
      final registry = TraitRegistry.withBuiltins();
      final diagnostics = TraitChecker.check(code, registry);
      expect(
        diagnostics.where((d) => d.code == 'unknown-trait').isEmpty,
        true,
      );
    });

    test('Test 12: 트레이트 구현 검사 - 알 수 없는 트레이트', () {
      const code = 'impl UnknownTrait for MyType { }';
      final registry = TraitRegistry.withBuiltins();
      final diagnostics = TraitChecker.check(code, registry);
      expect(
        diagnostics.any((d) => d.code == 'unknown-trait'),
        true,
      );
    });
  });

  group('에러 핸들링 (Error Handling)', () {
    test('Test 13: ResultType 생성', () {
      final result = ResultType(
        okType: FreeLangTypes.i32,
        errType: FreeLangTypes.string,
      );
      expect(result.name, 'Result<i32,string>');
    });

    test('Test 14: ResultType 호환성', () {
      final result1 = ResultType(
        okType: FreeLangTypes.i32,
        errType: FreeLangTypes.string,
      );
      final result2 = ResultType(
        okType: FreeLangTypes.i32,
        errType: FreeLangTypes.string,
      );
      expect(result1.isAssignableTo(result2), true);
    });

    test('Test 15: try-catch 구문 검사 - OK', () {
      const code = '''try {
  let x = 10
} catch(e: string) {
  print e
}''';
      final env = TypeEnvironment();
      final diagnostics = ErrorHandlingChecker.check(code, env);
      expect(
        diagnostics
            .where((d) => d.severity == DiagnosticSeverity.error)
            .isEmpty,
        true,
      );
    });

    test('Test 16: ? 연산자 - ResultType 사용', () {
      const code = 'let result: Result<i32, string> = Ok(42)\nlet value = result?';
      final env = TypeEnvironment();
      env.define('result', ResultType(
        okType: FreeLangTypes.i32,
        errType: FreeLangTypes.string,
      ));
      final diagnostics = ErrorHandlingChecker.check(code, env);
      // ? 연산자 사용이 가능해야 함
      expect(diagnostics.isEmpty, true);
    });

    test('Test 17: ? 연산자 - 비-Result 타입 오류', () {
      const code = 'let x: i32 = 10\nlet y = x?';
      final env = TypeEnvironment();
      env.define('x', FreeLangTypes.i32);
      final diagnostics = ErrorHandlingChecker.check(code, env);
      expect(
        diagnostics.any((d) => d.code == 'invalid-unwrap'),
        true,
      );
    });

    test('Test 18: 에러 타입 추론 - Ok/Err', () {
      const okExpr = 'Ok(42)';
      const errExpr = 'Err("message")';

      final okType = ErrorInferrer.inferResultLiteral(okExpr, TypeEnvironment());
      final errType =
          ErrorInferrer.inferResultLiteral(errExpr, TypeEnvironment());

      expect(okType is ResultType, true);
      expect(errType is ResultType, true);
    });
  });

  group('패턴 매칭 (Pattern Matching)', () {
    test('Test 19: LiteralPattern 매치', () {
      final pattern = LiteralPattern('42');
      expect(pattern.matches('42'), true);
      expect(pattern.matches('43'), false);
    });

    test('Test 20: WildcardPattern 매치', () {
      final pattern = WildcardPattern();
      expect(pattern.matches('anything'), true);
      expect(pattern.matches(''), true);
    });

    test('Test 21: ConstructorPattern - Some/None', () {
      final somePattern = ConstructorPattern('Some',
          [BindingPattern('x')]);
      expect(somePattern.toString(), contains('Some'));

      final nonePattern = ConstructorPattern('None');
      expect(nonePattern.toString(), 'None');
    });

    test('Test 22: TuplePattern 분해', () {
      final pattern = TuplePattern([
        BindingPattern('a'),
        BindingPattern('b'),
      ]);
      final bindings = pattern.bindings(TypeEnvironment());
      expect(bindings.containsKey('a'), true);
      expect(bindings.containsKey('b'), true);
    });

    test('Test 23: GuardPattern 조건', () {
      final pattern = GuardPattern(
        BindingPattern('n'),
        'n > 0',
      );
      expect(pattern.toString(), contains('if'));
      expect(pattern.bindings(TypeEnvironment()).containsKey('n'), true);
    });

    test('Test 24: 완전한 match (Some/None)', () {
      final arms = [
        MatchArm(ConstructorPattern('Some', [BindingPattern('x')]), 'x'),
        MatchArm(ConstructorPattern('None'), '0'),
      ];
      final optionType = OptionType(FreeLangTypes.i32);
      expect(PatternMatcher.isExhaustive(arms, optionType), true);
    });

    test('Test 25: 불완전한 match - 경고', () {
      final arms = [
