        // None이 없음
      ];
      final optionType = OptionType(FreeLangTypes.i32);
      expect(PatternMatcher.isExhaustive(arms, optionType), false);
    });
  });

  group('통합 테스트', () {
    test('제네릭 + 트레이트 통합', () {
      final registry = TraitRegistry.withBuiltins();

      // fn<T: Comparable>(a: T, b: T) -> T
      const code = 'fn<T: Comparable>(a: T, b: T) -> T { a }';
      final traitDiagnostics = TraitChecker.check(code, registry);
